sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.ProjectAPI();
    const response = api.driveTransfer(
        inputs.projectId,
        inputs.locationId,
        inputs.jobName,
        inputs.ticketNumber,
        inputs.ownerEmail,
        inputs.newOwnerEmail,
        String(inputs.fileIds).split(",")
    );

    if (response.error || response.status != 200) {
        outputs.error = true;
        outputs.response = !gs.nil(response.errorMessage) ?
            response.errorMessage :
            JSON.stringify(JSON.parse(response.responseBody));
    } else {
        outputs.error = false;
        ouptuts.response = "";
    }

})(inputs, outputs);

